representation.shell_command:
set -eu
{
  plink2 --version
  if command -v python >/dev/null 2>&1; then python --version; else echo no-python; fi
  if command -v python3 >/dev/null 2>&1; then python3 --version; else echo no-python3; fi
} > runtime.txt

